import express from "express";
import { fileURLToPath } from "node:url";
import { addTask, deleteTask, listTasks, updateTask } from "./db.js";

const publicDir = fileURLToPath(new URL("../public", import.meta.url));

function validateEstimate(value) {
  if (value === undefined || value === null) return true;
  return typeof value === "number" && Number.isFinite(value) && value >= 0;
}

const ESTIMATE_ERROR = { error: "estimate must be a non-negative number" };

/** Build the Express app around a database, so tests can use an in-memory one. */
export function createApp(db) {
  const app = express();
  app.use(express.json({ limit: "10kb" }));
  app.use(express.static(publicDir));

  app.get("/api/tasks", (req, res) => res.json(listTasks(db)));

  app.post("/api/tasks", (req, res) => {
    const title = typeof req.body?.title === "string" ? req.body.title.trim() : "";
    if (!title) return res.status(400).json({ error: "title is required" });
    const estimate = req.body.estimate;
    if (!validateEstimate(estimate)) return res.status(400).json(ESTIMATE_ERROR);
    res.status(201).json(addTask(db, { title, estimate }));
  });

  app.patch("/api/tasks/:id", (req, res) => {
    const body = req.body ?? {};
    if ("estimate" in body && !validateEstimate(body.estimate)) {
      return res.status(400).json(ESTIMATE_ERROR);
    }
    const fields = {};
    for (const key of ["title", "done", "estimate"]) {
      if (key in body) fields[key] = body[key];
    }
    const task = updateTask(db, Number(req.params.id), fields);
    if (!task) return res.status(404).json({ error: "not found" });
    res.json(task);
  });

  app.delete("/api/tasks/:id", (req, res) => {
    if (!deleteTask(db, Number(req.params.id))) return res.status(404).json({ error: "not found" });
    res.status(204).end();
  });

  return app;
}

