import assert from "node:assert/strict";
import { after, before, describe, it } from "node:test";
import { createApp } from "../src/app.js";
import { openDb } from "../src/db.js";

describe("tasks API", () => {
  let server;
  let base;

  before(async () => {
    server = createApp(openDb()).listen(0);
    await new Promise((resolve) => server.once("listening", resolve));
    base = `http://127.0.0.1:${server.address().port}`;
  });
  after(() => server.close());

  const json = (path, method, body) =>
    fetch(base + path, { method, headers: { "Content-Type": "application/json" }, body: body && JSON.stringify(body) });

  it("starts empty", async () => {
    const res = await fetch(`${base}/api/tasks`);
    assert.deepEqual(await res.json(), []);
  });

  it("creates, lists, updates and deletes a task", async () => {
    const created = await json("/api/tasks", "POST", { title: "  buy milk " });
    assert.equal(created.status, 201);
    const task = await created.json();
    assert.equal(task.title, "buy milk");
    assert.equal(task.done, 0);

    const done = await (await json(`/api/tasks/${task.id}`, "PATCH", { done: true })).json();
    assert.equal(done.done, 1);
    assert.equal(done.title, "buy milk");

    const all = await (await fetch(`${base}/api/tasks`)).json();
    assert.equal(all.length, 1);

    assert.equal((await json(`/api/tasks/${task.id}`, "DELETE")).status, 204);
    assert.deepEqual(await (await fetch(`${base}/api/tasks`)).json(), []);
  });

  it("rejects an empty title", async () => {
    const res = await json("/api/tasks", "POST", { title: "   " });
    assert.equal(res.status, 400);
  });

  it("returns 404 for a task that does not exist", async () => {
    assert.equal((await json("/api/tasks/999", "PATCH", { done: true })).status, 404);
    assert.equal((await json("/api/tasks/999", "DELETE")).status, 404);
  });
});

describe("tasks sorting", () => {
  let server;
  let base;

  before(async () => {
    const db = openDb();
    const ins = db.prepare("INSERT INTO tasks (title, done, created_at) VALUES (?, 0, ?)");
    ins.run("a", "2024-01-01T00:00:00.000Z"); // id 1
    ins.run("b", "2024-01-02T00:00:00.000Z"); // id 2
    ins.run("c", "2024-01-02T00:00:00.000Z"); // id 3 (tie with b)
    server = createApp(db).listen(0);
    await new Promise((resolve) => server.once("listening", resolve));
    base = `http://127.0.0.1:${server.address().port}`;
  });
  after(() => server.close());

  const ids = async (qs) => (await (await fetch(`${base}/api/tasks${qs}`)).json()).map((t) => t.id);

  it("defaults to created_at desc, id desc", async () => {
    assert.deepEqual(await ids(""), [3, 2, 1]);
  });

  it("sorts desc explicitly", async () => {
    assert.deepEqual(await ids("?sort=created_at&order=desc"), [3, 2, 1]);
  });

  it("sorts asc with id tiebreaker", async () => {
    assert.deepEqual(await ids("?sort=created_at&order=asc"), [1, 2, 3]);
  });

  it("rejects invalid sort and order", async () => {
    const a = await fetch(`${base}/api/tasks?sort=bogus`);
    assert.equal(a.status, 400);
    assert.ok((await a.json()).error);
    const b = await fetch(`${base}/api/tasks?order=sideways`);
    assert.equal(b.status, 400);
    assert.ok((await b.json()).error);
  });
});
